               const digit_grouping<Char>& grouping) -> OutputIt {
  static_assert(std::is_same<uint64_or_128_t<UInt>, UInt>::value, "");

  int num_digits = 1;
  {
    auto counted = value;
    for (;;) {
      if (counted < 10) break;
      if (counted < 100) {
        num_digits += 1;
        break;
      }
      if (counted < 1000) {
        num_digits += 2;
        break;
      }
      if (counted < 10000) {
        num_digits += 3;
        break;
      }
      counted /= 10000u;
      num_digits += 4;
    }
  }

  char digits[40];
  {
    char* ptr = digits + num_digits;
    auto formatted = value;
